from pathlib import Path
import shutil

ROOT = Path.cwd()
DB = ROOT / 'database' / 'db.py'
APP = ROOT / 'app.py'

if not DB.exists() or not APP.exists():
    raise SystemExit('Run this script from the TextEncode project root (where app.py and database/db.py exist).')

for path in (DB, APP):
    backup = path.with_suffix(path.suffix + '.phase3.bak')
    if not backup.exists():
        shutil.copy2(path, backup)

# Patch database schema and evidence API.
db = DB.read_text(encoding='utf-8-sig')
anchor = '        add_col("mentions", "deleted_at", "TEXT DEFAULT NULL")'
if 'add_col("evidence_bundles", "source_type"' not in db:
    if anchor not in db:
        raise SystemExit('Could not find schema migration anchor in database/db.py. No patch applied.')
    db = db.replace(anchor, anchor + '''\n        # Phase 3: structured citation and provenance metadata for evidence bundles.\n        add_col("evidence_bundles", "source_type", "TEXT")\n        add_col("evidence_bundles", "source_identifier", "TEXT")\n        add_col("evidence_bundles", "author", "TEXT")\n        add_col("evidence_bundles", "source_title", "TEXT")\n        add_col("evidence_bundles", "publisher", "TEXT")\n        add_col("evidence_bundles", "publication_year", "INTEGER")\n        add_col("evidence_bundles", "page_reference", "TEXT")\n        add_col("evidence_bundles", "url", "TEXT")\n        add_col("evidence_bundles", "access_date", "TEXT")\n        add_col("evidence_bundles", "verification_status", "TEXT NOT NULL DEFAULT 'unverified'")\n        add_col("evidence_bundles", "researcher_note", "TEXT")\n''')
    db = db.replace('SCHEMA_VERSION = 5', 'SCHEMA_VERSION = 6')
old = '''def add_evidence_bundle(conn, rel_id: str, domain: str, source_text: str, context: str) -> int:\n    conn.execute("INSERT INTO evidence_bundles (relationship_id, evidence_domain, source_text, context, created_at) VALUES (?, ?, ?, ?, ?)", (rel_id, domain, source_text, context, utc_now()))\n    return conn.execute("SELECT last_insert_rowid()").fetchone()[0]'''
new = '''def add_evidence_bundle(\n    conn, rel_id: str, domain: str, source_text: str, context: str = "", *,\n    source_type: str | None = None, source_identifier: str | None = None,\n    author: str | None = None, source_title: str | None = None,\n    publisher: str | None = None, publication_year: int | None = None,\n    page_reference: str | None = None, url: str | None = None,\n    access_date: str | None = None, verification_status: str = "unverified",\n    researcher_note: str | None = None,\n) -> int:\n    allowed = {"unverified", "checked", "corroborated", "contested", "rejected"}\n    if verification_status not in allowed:\n        raise ValueError(f"Invalid verification status: {verification_status}")\n    if not source_text or not source_text.strip():\n        raise ValueError("Evidence source text cannot be empty.")\n    if publication_year is not None and not (1 <= int(publication_year) <= 9999):\n        raise ValueError("Publication year must be between 1 and 9999.")\n    conn.execute(\n        """INSERT INTO evidence_bundles\n        (relationship_id, evidence_domain, source_text, context, created_at,\n         source_type, source_identifier, author, source_title, publisher,\n         publication_year, page_reference, url, access_date,\n         verification_status, researcher_note)\n        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",\n        (rel_id, domain, source_text.strip(), context, utc_now(), source_type,\n         source_identifier, author, source_title, publisher, publication_year,\n         page_reference, url, access_date, verification_status, researcher_note),\n    )\n    return conn.execute("SELECT last_insert_rowid()").fetchone()[0]'''
if old in db:
    db = db.replace(old, new)
elif 'def add_evidence_bundle(' not in db:
    raise SystemExit('Could not find add_evidence_bundle() in database/db.py. No patch applied.')
DB.write_text(db, encoding='utf-8')

# Patch the active Relationships page evidence form, retaining existing evidence records.
app = APP.read_text(encoding='utf-8-sig')
old_ui = '''                        st.markdown("**Evidence bundles**")\n                        if evidence:\n                            for item in evidence:\n                                with st.container(border=True):\n                                    st.markdown(\n                                        f"**{item['evidence_domain']}**"\n                                    )\n                                    st.write(item["source_text"])\n                                    if item["context"]:\n                                        st.caption(item["context"])\n                                    if st.button(\n                                        "Delete evidence",\n                                        key=f"delete_evidence_{item['evidence_id']}",\n                                    ):\n                                        with db.get_connection() as conn:\n                                            db.delete_evidence_bundle(\n                                                conn,\n                                                item["evidence_id"],\n                                            )\n                                        safe_rerun()\n                        else:\n                            st.info("No evidence bundles have been attached.")\n\n                        with st.form(\n                            f"add_evidence_{relation['relationship_id']}"\n                        ):\n                            domain = st.selectbox(\n                                "Evidence domain",\n                                ["Literary", "Historical", "Geographical"],\n                            )\n                            source_text = st.text_area(\n                                "Evidence passage / source text *"\n                            )\n                            context = st.text_input(\n                                "Reference or context"\n                            )\n                            add_evidence = st.form_submit_button(\n                                "Attach Evidence",\n                            )\n\n                        if add_evidence:\n                            if not source_text.strip():\n                                st.error("Evidence text is required.")\n                            else:\n                                with db.get_connection() as conn:\n                                    db.add_evidence_bundle(\n                                        conn,\n                                        relation["relationship_id"],\n                                        domain,\n                                        source_text.strip(),\n                                        context.strip(),\n                                    )\n                                safe_rerun()'''
new_ui = '''                        st.markdown("**Evidence bundles and source provenance**")\n                        if evidence:\n                            for item in evidence:\n                                with st.container(border=True):\n                                    st.markdown(f"**{item['evidence_domain']} · {item['verification_status'] or 'unverified'}**")\n                                    st.write(item["source_text"])\n                                    citation_parts = [item["author"], item["source_title"], item["publisher"], str(item["publication_year"]) if item["publication_year"] else None, item["page_reference"]]\n                                    citation = ", ".join(str(x) for x in citation_parts if x)\n                                    if citation:\n                                        st.caption(citation)\n                                    if item["source_identifier"]:\n                                        st.caption(f"Source ID: {item['source_identifier']}")\n                                    if item["url"]:\n                                        st.markdown(f"[Open source]({item['url']})")\n                                    if item["context"]:\n                                        st.caption(f"Context: {item['context']}")\n                                    if item["researcher_note"]:\n                                        st.write(f"Researcher note: {item['researcher_note']}")\n                                    if st.button("Delete evidence", key=f"delete_evidence_{item['evidence_id']}"):\n                                        with db.get_connection() as conn:\n                                            db.delete_evidence_bundle(conn, item["evidence_id"])\n                                        safe_rerun()\n                        else:\n                            st.info("No evidence bundles have been attached.")\n\n                        with st.form(f"add_evidence_{relation['relationship_id']}"):\n                            domain = st.selectbox("Evidence domain", ["Literary", "Historical", "Geographical", "Archival", "Scholarly", "Other"])\n                            source_text = st.text_area("Evidence passage / source text *")\n                            context = st.text_input("Context or quotation location")\n                            source_type = st.selectbox("Source type", ["Book", "Journal article", "Archive", "Website", "Newspaper", "Map", "Interview", "Other"])\n                            author = st.text_input("Author / creator")\n                            source_title = st.text_input("Source title")\n                            publisher = st.text_input("Publisher / repository")\n                            publication_year_text = st.text_input("Publication year (optional)")\n                            page_reference = st.text_input("Page / folio / section")\n                            source_identifier = st.text_input("DOI / ISBN / archive ID / catalogue number")\n                            url = st.text_input("Source URL")\n                            access_date = st.text_input("Access date (YYYY-MM-DD, optional)")\n                            verification_status = st.selectbox("Evidence verification", ["unverified", "checked", "corroborated", "contested", "rejected"])\n                            researcher_note = st.text_area("Researcher note / rationale")\n                            add_evidence = st.form_submit_button("Attach structured evidence")\n\n                        if add_evidence:\n                            if not source_text.strip():\n                                st.error("Evidence text is required.")\n                            else:\n                                try:\n                                    year = int(publication_year_text) if publication_year_text.strip() else None\n                                    with db.get_connection() as conn:\n                                        db.add_evidence_bundle(\n                                            conn, relation["relationship_id"], domain, source_text, context,\n                                            source_type=source_type, source_identifier=source_identifier.strip() or None,\n                                            author=author.strip() or None, source_title=source_title.strip() or None,\n                                            publisher=publisher.strip() or None, publication_year=year,\n                                            page_reference=page_reference.strip() or None, url=url.strip() or None,\n                                            access_date=access_date.strip() or None,\n                                            verification_status=verification_status,\n                                            researcher_note=researcher_note.strip() or None,\n                                        )\n                                    safe_rerun()\n                                except (ValueError, TypeError) as exc:\n                                    st.error(f"Could not attach evidence: {exc}")'''
if old_ui in app:
    app = app.replace(old_ui, new_ui)
elif 'Attach structured evidence' not in app:
    raise SystemExit('Could not find the active Relationships page evidence UI block. Database file was patched; app.py remains backed up and unchanged.')
APP.write_text(app, encoding='utf-8')
print('Phase 3 patch applied. Backups: database/db.py.phase3.bak and app.py.phase3.bak')
